import React from "react";

const LoginPage = () => {
  return (
    <div className="module-page">
      <h2>Login</h2>
      <div className="card">
        <p>This project is prepared for Google OAuth integration in the next backend security step.</p>
        <button className="btn-primary" type="button">Continue with Google (Placeholder)</button>
      </div>
    </div>
  );
};

export default LoginPage;
